# PTX source for fp16 GEMM (C = A @ B) on SM80
PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry gemm_fp16(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    // -------------------------------------------------
    // Register declaration
    // -------------------------------------------------
    .reg .pred   %p<3>;
    .reg .s32    %r<9>;
    .reg .u64    %rd<13>;
    .reg .f16    %hf0, %hf1;
    .reg .f32    %f0, %f1, %f2;

    // -------------------------------------------------
    // Load kernel parameters
    // -------------------------------------------------
    ld.param.u64    %rd1, [A_ptr];
    ld.param.u64    %rd2, [B_ptr];
    ld.param.u64    %rd3, [C_ptr];
    ld.param.u32    %r8,  [N];          // matrix dimension

    // -------------------------------------------------
    // Thread / block indices
    // -------------------------------------------------
    mov.u32         %r0, %ctaid.x;     // blockIdx.x
    mov.u32         %r1, %ctaid.y;     // blockIdx.y
    mov.u32         %r2, %tid.x;       // threadIdx.x
    mov.u32         %r3, %tid.y;       // threadIdx.y

    // -------------------------------------------------
    // Compute global row and column
    // -------------------------------------------------
    mad.lo.s32      %r4, %r1, 16, %r3; // row = blockIdx.y*16 + threadIdx.y
    mad.lo.s32      %r5, %r0, 16, %r2; // col = blockIdx.x*16 + threadIdx.x

    // -------------------------------------------------
    // Bounds check – if outside matrix, exit
    // -------------------------------------------------
    setp.ge.s32     %p0, %r4, %r8;
    setp.ge.s32     %p1, %r5, %r8;
    or.pred         %p2, %p0, %p1;
    @%p2           bra DONE;

    // -------------------------------------------------
    // Compute base addresses
    // -------------------------------------------------
    // A row base: A + row * N * sizeof(half)
    cvt.u64.u32     %rd4, %r4;           // row
    cvt.u64.u32     %rd5, %r8;           // N
    mul.lo.u64      %rd6, %rd4, %rd5;    // row * N
    shl.b64         %rd6, %rd6, 1;       // *2 (half size)
    add.u64         %rd6, %rd1, %rd6;    // &A[row,0]

    // B column base: B + col * sizeof(half)
    cvt.u64.u32     %rd7, %r5;           // col
    shl.b64         %rd7, %rd7, 1;       // *2
    add.u64         %rd7, %rd2, %rd7;    // &B[0,col]

    // -------------------------------------------------
    // Initialize accumulator (float32)
    // -------------------------------------------------
    mov.f32         %f0, 0f00000000;     // acc = 0.0f

    // -------------------------------------------------
    // Loop over k dimension
    // -------------------------------------------------
    mov.u32         %r6, 0;              // k = 0
K_LOOP:
    setp.ge.u32     %p0, %r6, %r8;
    @%p0           bra K_DONE;

    // Load A[row,k] (half)
    cvt.u64.u32     %rd8, %r6;           // k
    shl.b64         %rd8, %rd8, 1;       // *2
    add.u64         %rd8, %rd6, %rd8;    // &A[row,k]
    ld.global.cv.f16 %hf0, [%rd8];

    // Load B[k,col] (half)
    // offset = k * N * sizeof(half)
    cvt.u64.u32     %rd9, %r6;           // k
    mul.lo.u64      %rd9, %rd9, %rd5;    // k * N
    shl.b64         %rd9, %rd9, 1;       // *2
    add.u64         %rd9, %rd7, %rd9;    // &B[k,col]
    ld.global.cv.f16 %hf1, [%rd9];

    // Convert to float32
    cvt.f32.f16     %f1, %hf0;
    cvt.f32.f16     %f2, %hf1;

    // Multiply‑accumulate
    fma.rn.f32      %f0, %f1, %f2, %f0;

    // k++
    add.u32         %r6, %r6, 1;
    bra.uni         K_LOOP;
K_DONE:

    // -------------------------------------------------
    // Convert accumulator back to half and store C[row,col]
    // -------------------------------------------------
    cvt.f16.f32     %hf0, %f0;

    // C address = C + (row * N + col) * sizeof(half)
    mul.lo.u64      %rd10, %rd4, %rd5;   // row * N
    add.u64         %rd10, %rd10, %rd7;  // row*N + col   (rd7 holds col*2, but we need col index)
    // rd7 currently = col*2, so we need col (index) not byte offset.
    // Recover col index by shifting right 1.
    shr.b64         %rd11, %rd7, 1;      // col as index
    add.u64         %rd10, %rd10, %rd11; // row*N + col
    shl.b64         %rd10, %rd10, 1;     // *2 (byte offset)
    add.u64         %rd10, %rd3, %rd10;  // &C[row,col]

    st.global.cv.f16 [%rd10], %hf0;

DONE:
    ret;
}
'''

