# PyTorch wrapper that loads and launches the PTX kernel
# -------------------------------------------------
import torch
import torch.nn as nn

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        # Load PTX module using the harness‑provided API
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.dtype == torch.float16 and B.dtype == torch.float16, \
            "Inputs must be float16 tensors"
        assert A.shape == B.shape and A.dim() == 2, \
            "Inputs must be square 2‑D tensors"

        N = A.shape[0]
        C = torch.empty_like(A)

        # Grid/Block configuration (16×16 threads per block)
        grid  = ((N + 15) // 16, (N + 15) // 16, 1)
        block = (16, 16, 1)

        # Arguments: raw pointers + dimension
        args = [A.data_ptr(), B.data_ptr(), C.data_ptr(), N]

        # Launch the kernel via the harness‑provided API
        ptx_launch(self.module, "gemm_fp16", grid, block, args)

        return C
